/**
 * Guard tests for HTML escaping on every markdown surface that reaches
 * `dangerouslySetInnerHTML`.
 *
 * Proposal section content is authored by other workspace members, generated by
 * the agent pipeline from uploaded tender documents, and can arrive from
 * marketplace templates. A component that hand-rolls markdown-to-HTML instead
 * of using the shared escaping renderer turns that into stored XSS against a
 * reviewer's authenticated session.
 */
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { escapeHtml, markdownToHtml } from "@/lib/markdown";

const REPO_ROOT = join(import.meta.dir, "..", "..", "..");

const XSS_PAYLOADS = [
  `<img src=x onerror="alert(1)">`,
  `<svg onload=alert(1)>`,
  `<script>alert(1)</script>`,
  `<iframe src="javascript:alert(1)"></iframe>`,
  `<a href="javascript:alert(1)">click</a>`,
  `"><img src=x onerror=alert(1)>`,
  `<body onload=alert(1)>`,
];

describe("markdownToHtml escaping", () => {
  // An attribute name such as `onerror=` may legitimately survive as escaped
  // *text*; what must never survive is an actual tag. Assert on emitted tags.
  const DANGEROUS_TAG = /<\s*\/?\s*(img|svg|script|iframe|body|a|object|embed|form|input|link|style|meta)\b/i;

  test.each(XSS_PAYLOADS)("neutralises %s", (payload) => {
    const html = markdownToHtml(payload);
    expect(html).not.toMatch(DANGEROUS_TAG);
    expect(html).toContain("&lt;");
  });

  test("escapes payloads embedded inside markdown constructs", () => {
    const html = markdownToHtml(
      [
        `# <img src=x onerror=alert(1)>`,
        ``,
        `- <svg onload=alert(1)>`,
        ``,
        `| <script>alert(1)</script> | b |`,
        `| --- | --- |`,
        `| c | d |`,
        ``,
        `> <iframe src=javascript:alert(1)>`,
      ].join("\n")
    );
    expect(html).not.toMatch(DANGEROUS_TAG);
  });

  test("still renders legitimate markdown structure", () => {
    const html = markdownToHtml("# Title\n\nSome **bold** text.\n\n- one\n- two");
    expect(html).toContain("<h1");
    expect(html).toContain("<strong>bold</strong>");
    expect(html).toContain("<li");
  });

  test("escapeHtml covers the characters that break out of a text node", () => {
    expect(escapeHtml(`<>&"`)).toBe("&lt;&gt;&amp;&quot;");
  });

  test("escapes ampersands before angle brackets so entities cannot be reformed", () => {
    // Wrong ordering yields `&lt;` from a literal `&amp;lt;`, re-forming a tag.
    expect(escapeHtml("&lt;img&gt;")).toBe("&amp;lt;img&amp;gt;");
  });
});

describe("no component hand-rolls a markdown renderer", () => {
  const COMPONENT_FILES = [
    "src/components/dashboard/proposal-builder-preview.tsx",
    "src/components/dashboard/markdown-studio-editor-inner.tsx",
  ];

  test.each(COMPONENT_FILES)(
    "%s builds preview HTML via the shared escaping renderer",
    (relativePath) => {
      const source = readFileSync(join(REPO_ROOT, relativePath), "utf8");
      expect(source).toContain("markdownToHtml");
      // The regression was a local `.replace(/^### .../)` chain feeding
      // dangerouslySetInnerHTML without escaping first.
      expect(source).not.toMatch(/replace\(\s*\/\^#{1,6}\s/);
    }
  );
});
